import socket
import random
import errno
import os

_original_socket_init = socket.socket.__init__
_original_connect = socket.socket.connect
_original_send = socket.socket.send
_original_sendall = socket.socket.sendall
_original_recv = socket.socket.recv

FAILURE_RATE = 0.15

def _patched_connect(self, address):
    if random.random() < FAILURE_RATE:
        error_choice = random.choice([
            errno.ECONNREFUSED,
            errno.ETIMEDOUT,
            errno.EADDRINUSE,
        ])
        raise OSError(error_choice, os.strerror(error_choice))
    return _original_connect(self, address)

def _patched_send(self, data, flags=0):
    if random.random() < FAILURE_RATE:
        error_choice = random.choice([
            errno.ECONNRESET,
            errno.EPIPE,
            errno.EMFILE,
        ])
        raise OSError(error_choice, os.strerror(error_choice))
    return _original_send(self, data, flags)

def _patched_sendall(self, data, flags=0):
    if random.random() < FAILURE_RATE:
        error_choice = random.choice([
            errno.ECONNRESET,
            errno.EPIPE,
            errno.EMFILE,
        ])
        raise OSError(error_choice, os.strerror(error_choice))
    return _original_sendall(self, data, flags)

def _patched_recv(self, bufsize, flags=0):
    if random.random() < FAILURE_RATE:
        error_choice = random.choice([
            errno.ECONNRESET,
            errno.ETIMEDOUT,
        ])
        raise OSError(error_choice, os.strerror(error_choice))
    return _original_recv(self, bufsize, flags)

socket.socket.connect = _patched_connect
socket.socket.send = _patched_send
socket.socket.sendall = _patched_sendall
socket.socket.recv = _patched_recv
